import{_ as e}from"./chunks/autonomous.DdFNL1Im.js";import{_ as o,o as a,c as r,a2 as i}from"./chunks/framework.CS-cBh1g.js";const b=JSON.parse('{"title":"Your first auto","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md"}'),s={name:"guide/quick-start.md"};function n(h,t,d,l,c,p){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="your-first-auto" tabindex="-1">Your first auto <a class="header-anchor" href="#your-first-auto" aria-label="Permalink to &quot;Your first auto&quot;">​</a></h1><p>This walks through building an auto, previewing it, and getting it into robot code. It takes about ten minutes. You don&#39;t need a robot; you do need the <a href="/Mayhem/guide/installation">desktop app</a>.</p><h2 id="_1-open-your-robot-code" tabindex="-1">1. Open your robot code <a class="header-anchor" href="#_1-open-your-robot-code" aria-label="Permalink to &quot;1. Open your robot code&quot;">​</a></h2><p>On <strong>Overview</strong>, click <strong>Choose robot code folder</strong> and pick your robot repository. If it has a <code>robot.mayhem.json</code>, Mayhem opens that project, linked to the file, so your edits save straight into the repo.</p><p>No project yet? Click the project name in the top bar and create one, then save it into the repo later with <strong>Settings → Agents and the project file → Save project file</strong>.</p><h2 id="_2-tell-mayhem-about-the-robot" tabindex="-1">2. Tell Mayhem about the robot <a class="header-anchor" href="#_2-tell-mayhem-about-the-robot" aria-label="Permalink to &quot;2. Tell Mayhem about the robot&quot;">​</a></h2><p>On <strong>Robot → Specs &amp; limits</strong>, enter the robot&#39;s length, width and drive limits (max speed, acceleration, turn speed). Every auto is planned with them, so use real numbers.</p><p>Add the <strong>typed inputs</strong> your auto will wait on, such as &quot;has a game piece&quot; or &quot;shooter ready&quot;. They become conditions in the routine and signals your robot code provides.</p><h2 id="_3-place-goals" tabindex="-1">3. Place goals <a class="header-anchor" href="#_3-place-goals" aria-label="Permalink to &quot;3. Place goals&quot;">​</a></h2><p><img src="'+e+'" alt="The Autonomous workspace"></p><p>Open <strong>Autonomous</strong> and create a routine. Drag the starting robot into place, then pick a tool above the field and click to place goals:</p><ul><li><strong>Pose</strong> (<code>W</code>): the robot gets to this point at this heading.</li><li><strong>Any heading</strong> (<code>T</code>): the robot gets here, whatever way it&#39;s facing.</li><li><strong>Pass through</strong> (<code>G</code>): the robot drives through without stopping.</li><li><strong>Draw</strong> (<code>D</code>): drag a route freehand; it becomes a few pass-through points and a final pose.</li></ul><p>Drag a goal&#39;s knob to turn it. Select a step to set <strong>Stop here</strong>, its speed limits, and under <strong>Advanced</strong> the actions, conditions and watchdog timeouts.</p><h2 id="_4-add-what-the-robot-does" tabindex="-1">4. Add what the robot does <a class="header-anchor" href="#_4-add-what-the-robot-does" aria-label="Permalink to &quot;4. Add what the robot does&quot;">​</a></h2><p>Right-click a step and choose <strong>Add action after</strong>. Give the action an ID like <code>intake.acquire</code>; your robot code will bind that ID to real code. Add a transition condition such as <code>pieceDetected</code> so the routine waits for the sensor instead of a timer.</p><h2 id="_5-preview-it" tabindex="-1">5. Preview it <a class="header-anchor" href="#_5-preview-it" aria-label="Permalink to &quot;5. Preview it&quot;">​</a></h2><p>Press <strong>Preview</strong> (Space). <strong>Path</strong> drives the route. <strong>With actions</strong> runs the routine like the robot will, waiting on the inputs and action results you set under <strong>Inputs &amp; events</strong>. Check that the badge above the field says <strong>Fits in auto</strong>.</p><p>Open <strong>Whole path → Map → Generate</strong> to let Mayhem choose speed caps and corner radii for each segment.</p><h2 id="_6-put-it-on-the-robot" tabindex="-1">6. Put it on the robot <a class="header-anchor" href="#_6-put-it-on-the-robot" aria-label="Permalink to &quot;6. Put it on the robot&quot;">​</a></h2><p>Generate the C++ header from the project:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B392F0;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> scripts/mayhem.mjs</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> cpp</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> robot.mayhem.json</span><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;"> src/main/include/MayhemProject.h</span></span></code></pre></div><p>Then bind your action and signal IDs on the runner and start it in autonomous. <a href="/Mayhem/robot-code/autos">Running autos</a> shows the whole robot side, including red-alliance flipping.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/Mayhem/suite/autonomous">Everything in Autonomous</a></li><li><a href="/Mayhem/guide/workflow">A week with Mayhem</a>: how autos, logs, reviews and agents fit together across a build week.</li></ul>',24)])])}const m=o(s,[["render",n]]);export{b as __pageData,m as default};
